  });

  it('rejects a booking for a user that does not exist', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId: 'missing-user', title: 'Sync', startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(404);
  });

  it('rejects moving a booking onto a time that conflicts with another active booking', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Movable');
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
    });
    expect(response.statusCode).toBe(409);
  });

  it('allows moving a booking to a new non-conflicting time', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { startsAt: inHours(40), endsAt: inHours(41) },
    });
    expect(response.statusCode).toBe(200);
  });

  it('does not conflict with itself when updating unrelated fields', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { title: 'Renamed again' },
    });
    expect(response.statusCode).toBe(200);
  });

  it('rejects updating a booking to a room that does not exist', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { roomId: 'missing-room' },
    });
    expect(response.statusCode).toBe(404);
  });
});

